-- 1) sys_dict_data 增加公式配置字段
ALTER TABLE sys_dict_data
ADD COLUMN formula_config TEXT NULL COMMENT '产品公式配置JSON(对应公式管理页)' AFTER img_url;

-- 2) 小料三节（id=73, style_sanjie/1）落库公式配置
UPDATE sys_dict_data
SET formula_config = '{"productName":"小料三节","vars":["总高","总宽","数量","颜色","网子","把手","加杆","下固定","单价","把手方向"],"孔位":[{"cond":"下固定=0","expr":"总高/3-6"},{"cond":"下固定>0","expr":"(总高-下固定)/2-6"}],"型材":{"外框宽":{"expr":"总宽-28","mult":"2*数量"},"外框高":{"expr":"总高-28","mult":"2*数量"},"横杆":{"expr":"总宽-28","mult":"2*数量"},"内扇宽":{"expr":"总宽-27.5","mult":"2*数量"},"内扇高":[{"expr":"总高/3-6+13","mult":"2*数量","cond":"下固定=0"},{"expr":"孔位+13","mult":"2*数量","cond":"下固定>0"}],"加杆":[{"expr":"总高/3-6-36","mult":"2*数量","cond":"{加杆=有,下固定=0}"},{"expr":"孔位-36","mult":"2*数量","cond":"{加杆=有,下固定>0}"}],"小短杆":{"expr":"孔位-36","mult":"1*数量","cond":"加杆=全防护"},"短横杆":{"expr":"外框宽-182","mult":"2*数量","cond":"加杆=全防护"}},"纱网":{"上网":[{"w":"内扇宽+15","h":"内扇高-10","mult":"1*数量"}],"下网":[{"w":"内扇宽+15","h":"内扇高-10","mult":"1*数量","cond":"下固定=0"},{"w":"内扇宽+15","h":"下固定-5+3","mult":"1*数量","cond":"下固定>0"}],"中网":[{"w":"内扇宽-36","h":"内扇高-35","mult":"1*数量"}]},"面积":[{"cond":"总高*总宽*0.000001<=1","expr":"1*数量"},{"cond":"总高*总宽*0.000001>1","expr":"总高*总宽*0.000001*数量"}],"金额明细":{"基本金额":{"expr":"单价*面积"},"总高加价":[{"expr":"5*面积","cond":"总高>1399"},{"expr":"5*面积","cond":"总高>1499"}],"把手加价":{"expr":"5*数量","cond":"把手=一字密码锁"}}}'
WHERE id = 73;

